444	/************************************************************************/
445	/*                       GXFReadRawScanlineFrom()                       */
446	/************************************************************************/
447	
448	static CPLErr GXFReadRawScanlineFrom( GXFInfo_t * psGXF, vsi_l_offset iOffset,
449	                                      vsi_l_offset * pnNewOffset, double * padfLineBuf )
450	
451	{
452	    const char	*pszLine;
453	    int		nValuesRead = 0, nValuesSought = psGXF->nRawXSize;
454	
455	    if( VSIFSeekL( psGXF->fp, iOffset, SEEK_SET ) != 0 )
456	        return CE_Failure;
457	
458	    while( nValuesRead < nValuesSought )
459	    {
460	        pszLine = CPLReadLineL( psGXF->fp );
461	        if( pszLine == NULL )
462	            break;
463	
464	/* -------------------------------------------------------------------- */
465	/*      Uncompressed case.                                              */
466	/* -------------------------------------------------------------------- */
467	        if( psGXF->nGType == 0 )
468	        {
469	            /* we could just tokenize the line, but that's pretty expensive.
470	               Instead I will parse on white space ``by hand''. */
471	            while( *pszLine != '\0' && nValuesRead < nValuesSought )
472	            {
473	                int		i;
474	
475	                /* skip leading white space */
476	                for( ; isspace((unsigned char)*pszLine); pszLine++ ) {}
477	
478	                /* Skip the data value (non white space) */
479	                for( i = 0; pszLine[i] != '\0' && !isspace((unsigned char)pszLine[i]); i++) {}
480	
481	                if( strncmp(pszLine,psGXF->szDummy,i) == 0 )
482	                {
483	                    padfLineBuf[nValuesRead++] = psGXF->dfSetDummyTo;
484	                }
485	                else
486	                {
487	                    padfLineBuf[nValuesRead++] = CPLAtof(pszLine);
488	                }
489	
490	                /* skip further whitespace */
491	                for( pszLine += i; isspace((unsigned char)*pszLine); pszLine++ ) {}
492	            }
493	        }
494	
495	/* -------------------------------------------------------------------- */
496	/*      Compressed case.                                                */
497	/* -------------------------------------------------------------------- */
498	        else
499	        {
500	            size_t nLineLenOri = strlen(pszLine);
501	            int nLineLen = (int)nLineLenOri;
502	
503	            while( *pszLine != '\0' && nValuesRead < nValuesSought )
504	            {
505	                if( nLineLen < psGXF->nGType )
506	                    return CE_Failure;
507	
508	                if( pszLine[0] == '!' )
509	                {
510	                    padfLineBuf[nValuesRead++] = psGXF->dfSetDummyTo;
511	                }
512	                else if( pszLine[0] == '"' )
513	                {
514	                    int		nCount, i;
515	                    double	dfValue;
516	
517	                    pszLine += psGXF->nGType;
518	                    nLineLen -= psGXF->nGType;
519	                    if( nLineLen < psGXF->nGType )
520	                    {
521	                        pszLine = CPLReadLineL( psGXF->fp );
522	                        if( pszLine == NULL )
523	                            return CE_Failure;
524	                        nLineLenOri = strlen(pszLine);
525	                        nLineLen = (int)nLineLenOri;
526	                        if( nLineLen < psGXF->nGType )
527	                            return CE_Failure;
528	                    }
529	
530	                    nCount = (int) GXFParseBase90( psGXF, pszLine, FALSE);
531	                    pszLine += psGXF->nGType;
532	                    nLineLen -= psGXF->nGType;
533	
534	                    if( nLineLen < psGXF->nGType )
535	                    {
536	                        pszLine = CPLReadLineL( psGXF->fp );
537	                        if( pszLine == NULL )
538	                            return CE_Failure;
539	                        nLineLenOri = strlen(pszLine);
540	                        nLineLen = (int)nLineLenOri;
541	                        if( nLineLen < psGXF->nGType )
542	                            return CE_Failure;
543	                    }
544	
545	                    if( *pszLine == '!' )
546	                        dfValue = psGXF->dfSetDummyTo;
547	                    else
548	                        dfValue = GXFParseBase90( psGXF, pszLine, TRUE );
549	
550	                    if( nValuesRead + nCount > nValuesSought )
551	                    {
552	                        CPLError(CE_Failure, CPLE_AppDefined, "Wrong count value");
553	                        return CE_Failure;
554	                    }
555	
556	                    for( i=0; i < nCount && nValuesRead < nValuesSought; i++ )
557	                        padfLineBuf[nValuesRead++] = dfValue;
558	                }
559	                else
560	                {
561	                    padfLineBuf[nValuesRead++] =
562	                        GXFParseBase90( psGXF, pszLine, TRUE );
563	                }
564	
565	                pszLine += psGXF->nGType;
566	                nLineLen -= psGXF->nGType;
567	            }
568	        }
569	    }
570	
571	/* -------------------------------------------------------------------- */
572	/*      Return the new offset, if requested.                            */
573	/* -------------------------------------------------------------------- */
574	    if( pnNewOffset != NULL )
575	    {
576	        *pnNewOffset = VSIFTellL( psGXF->fp );
577	    }
578	
579	    return CE_None;
580	}
