582	/************************************************************************/
583	/*                           GXFGetScanline()                           */
584	/************************************************************************/
585	
586	/**
587	 * Read a scanline of raster data from GXF file.
588	 *
589	 * This function operates similarly to GXFGetRawScanline(), but it
590	 * attempts to mirror data horizontally or vertically based on the #SENSE
591	 * flag to return data in a top to bottom, and left to right organization.
592	 * If the file is organized in columns (#SENSE is GXFS_UR_DOWN, GXFS_UL_DOWN,
593	 * GXFS_LR_UP, or GXFS_LL_UP) then this function will fail, returning
594	 * CE_Failure, and reporting a sense error.
595	 *
596	 * See GXFGetRawScanline() for other notes.
597	 *
598	 * @param hGXF the GXF file handle, as returned from GXFOpen().
599	 * @param iScanline the scanline to read, zero is the top scanline.
600	 * @param padfLineBuf a buffer of doubles into which the scanline pixel
601	 * values are read.  This must be at least as long as a scanline.
602	 *
603	 * @return CE_None if access succeeds or CE_Failure if something goes wrong.
604	 */
605	
606	CPLErr GXFGetScanline( GXFHandle hGXF, int iScanline, double * padfLineBuf )
607	
608	{
609	    GXFInfo_t	*psGXF = (GXFInfo_t *) hGXF;
610	    CPLErr	nErr;
611	    int		iRawScanline;
612	
613	    if( psGXF->nSense == GXFS_LL_RIGHT
614	        || psGXF->nSense == GXFS_LR_LEFT )
615	    {
616	        iRawScanline = psGXF->nRawYSize - iScanline - 1;
617	    }
618	
